import{b as o,O as a,g as e,j as l}from"./chunks/framework.DcaUmd3X.js";const p=JSON.parse('{"title":"从技能到文化","description":"","frontmatter":{},"headers":[],"relativePath":"testing/summary/culture/index.md","filePath":"测试理论与实践/6.总结与展望/18.从技能到文化.md","lastUpdated":1781625968000}'),i={name:"testing/summary/culture/index.md"};function r(u,t,n,s,h,q){return a(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="从技能到文化" tabindex="-1">从技能到文化 <a class="header-anchor" href="#从技能到文化" aria-label="Permalink to &quot;从技能到文化&quot;">​</a></h1><blockquote><p>学会测试方法论可以让你成为一个好的测试人员。但要让你所在的团队变好，需要的不只是方法——是文化。</p></blockquote><h2 id="个人能力的三个台阶" tabindex="-1">个人能力的三个台阶 <a class="header-anchor" href="#个人能力的三个台阶" aria-label="Permalink to &quot;个人能力的三个台阶&quot;">​</a></h2><p>测试人员的成长大致有三步。不是每个测试人员都要走到第三步，但每上一级，你的价值不是翻倍，是翻十倍。</p><h3 id="第一阶-会测" tabindex="-1">第一阶：会测 <a class="header-anchor" href="#第一阶-会测" aria-label="Permalink to &quot;第一阶：会测&quot;">​</a></h3><p>能独立完成功能测试——拿到需求、设计用例、执行测试、写 Bug 报告。能熟练使用等价类、边界值、错误猜测，能写清晰的 Bug 报告。<strong>这是及格线。</strong></p><p>达到这一阶的关键不是学更多方法，而是<strong>测过足够多的东西</strong>。经验的积累无法速成——你踩过的坑越多，下次挖得越深。</p><h3 id="第二阶-会想" tabindex="-1">第二阶：会想 <a class="header-anchor" href="#第二阶-会想" aria-label="Permalink to &quot;第二阶：会想&quot;">​</a></h3><p>不只会&quot;按用例测&quot;，还有自己的测试策略——拿到一个新需求，脑子里自动形成一张&quot;哪里最危险、哪里该深挖&quot;的地图。能独立写探测章程、做限时探索会话、设计自动化验收测试。</p><p><strong>这一阶的标志是：你开始发现别人发现不了的 bug。</strong> 不是因为运气好，而是因为你知道往哪看。</p><h3 id="第三阶-会建" tabindex="-1">第三阶：会建 <a class="header-anchor" href="#第三阶-会建" aria-label="Permalink to &quot;第三阶：会建&quot;">​</a></h3><p>不只会测自己的东西，还能<strong>让别人测得更高效</strong>——写测试框架、搭建 CI 管道、培训团队。你能把一个手工测试密集的团队，一步步带上自动化回归的轨道。</p><p>这一阶的本质是：你的影响力从&quot;你自己测得好&quot;变成了&quot;整个团队测得好&quot;。<a href="/testing/engineering/google-testing.html">Google 测试体系</a>一章讲的 SET 角色就是这一阶的专业化形态。</p><h2 id="团队实践-从一个人到一群人" tabindex="-1">团队实践：从一个人到一群人 <a class="header-anchor" href="#团队实践-从一个人到一群人" aria-label="Permalink to &quot;团队实践：从一个人到一群人&quot;">​</a></h2><p>一个人的能力强，不代表团队的测试能力强。从个人到团队，有几道坎要过。</p><h3 id="第一道坎-知识不流动" tabindex="-1">第一道坎：知识不流动 <a class="header-anchor" href="#第一道坎-知识不流动" aria-label="Permalink to &quot;第一道坎：知识不流动&quot;">​</a></h3><p>A 知道支付模块有哪些坑，B 接手时一无所知。解决方案不是&quot;让 A 写更多文档&quot;——是建立<strong>轻量级的知识传递机制</strong>：</p><ul><li>探索会话的笔记分享到团队频道（不是归档，是分享）</li><li>Bug 回顾会上不只是过数字，而是讲&quot;这个 bug 是怎么被发现的、换个模块怎么防&quot;</li><li>结对测试让隐性知识在两颗大脑之间直接传递</li></ul><h3 id="第二道坎-自动化只有一个人会写" tabindex="-1">第二道坎：自动化只有一个人会写 <a class="header-anchor" href="#第二道坎-自动化只有一个人会写" aria-label="Permalink to &quot;第二道坎：自动化只有一个人会写&quot;">​</a></h3><p>某个测试脚本是张三写的，张三请假了脚本挂了谁也修不了。解决方案是<strong>把自动化能力扩散</strong>：</p><ul><li>自动化代码和产品代码一样要经过代码审查——不只是查 bug，也是让别人看懂</li><li>测试框架的文档不是&quot;API 参考&quot;，而是&quot;怎么加一个新测试&quot;的完整指南</li><li>开发人员写单元测试，SET 写框架，TE 写验收场景——自动化不是一个人的工作</li></ul><h3 id="第三道坎-质量被当成测试的事" tabindex="-1">第三道坎：质量被当成测试的事 <a class="header-anchor" href="#第三道坎-质量被当成测试的事" aria-label="Permalink to &quot;第三道坎：质量被当成测试的事&quot;">​</a></h3><p>开发写完扔给测试，产品只管需求不管验收。解决方案在<a href="/testing/engineering/agile-testing-1.html">敏捷测试（上）</a>一章已经讲了——<strong>全团队对质量负责</strong>。但真正落地需要：</p><ul><li>产品经理参与验收测试的编写（至少参与评审）</li><li>开发把&quot;测试通过&quot;作为完成的定义，而不是&quot;代码写完了&quot;</li><li>管理层理解并支持测试基础设施的投入——不是&quot;测个功能要花三周建自动化&quot;，而是&quot;建了自动化以后每次测只需要五分钟&quot;</li></ul><h2 id="组织体系-让好做法不依赖好人" tabindex="-1">组织体系：让好做法不依赖好人 <a class="header-anchor" href="#组织体系-让好做法不依赖好人" aria-label="Permalink to &quot;组织体系：让好做法不依赖好人&quot;">​</a></h2><p>个人和团队再强，如果没有组织层面的支持，好做法也会随人走而消失。</p><h3 id="测试基础设施建设" tabindex="-1">测试基础设施建设 <a class="header-anchor" href="#测试基础设施建设" aria-label="Permalink to &quot;测试基础设施建设&quot;">​</a></h3><p><a href="/testing/engineering/continuous-delivery-1.html">持续交付（上）</a> 和 <a href="/testing/engineering/continuous-delivery-2.html">持续交付（下）</a>两章讲的管道不是一次搭好就完了。需要有持续的投入——升级工具版本、优化慢测试、补充新的检查规则。<strong>如果测试基础设施的维护永远排在所有业务需求的后面，它就会慢慢腐化。</strong></p><p>组织结构上，可以参考 <a href="/testing/engineering/google-testing.html">Google 测试体系</a>一章的工程生产力部门思路——不管你们有没有专门的部门，至少要有一个人被明确授权对测试基础设施负责。不是&quot;有空搞一下&quot;，而是&quot;这件事是你的责任&quot;。</p><h3 id="测试能力的招聘和培养" tabindex="-1">测试能力的招聘和培养 <a class="header-anchor" href="#测试能力的招聘和培养" aria-label="Permalink to &quot;测试能力的招聘和培养&quot;">​</a></h3><p>招测试人员时，不要只问&quot;你用过什么测试工具&quot;。问：</p><ul><li>&quot;描述一个你发现的印象最深的 bug，你是怎么找到它的？&quot;</li><li>&quot;给你一个功能，你怎么决定该测什么、不测什么？&quot;</li></ul><p>第一个问题考察经验深度，第二个问题考察策略思维。<a href="/testing/methodology/exploratory-testing-1.html">探索式测试（上）</a> 和 <a href="/testing/methodology/exploratory-testing-2.html">探索式测试（下）</a>两章讲的那些能力——观察、变量识别、评估——才是区分好测试人员和普通测试人员的核心。</p><p>对已有团队的培养，不需要送出去上昂贵的培训课。最有效的方式是：</p><ul><li>结对测试（见探索式测试（下）一章）——让能力强的人带能力弱的人</li><li>测试用例评审（见<a href="/testing/engineering/agile-testing-2.html">敏捷测试（下）</a>一章）——和代码审查一样，让测试用例被同事审视</li><li>内部技术分享——每个月一次，一个人分享一个自己发现的测试技巧</li></ul><h3 id="从度量到改进" tabindex="-1">从度量到改进 <a class="header-anchor" href="#从度量到改进" aria-label="Permalink to &quot;从度量到改进&quot;">​</a></h3><p><a href="/testing/execution/bug-management.html">缺陷管理</a>一章讲的 Bug 度量——发现率、修复率、重开率——不是用来做绩效考核的。它们的正确用途是<strong>驱动改进行动</strong>：</p><ul><li>重开率高 → 是不是开发没做根因分析？</li><li>某个模块 Bug 密集 → 是不是需要重构？</li><li>自动化通过率持续下降 → 是不是 flaky 测试在腐蚀管道？</li></ul><p>度量不是为了证明谁做得好，是为了发现哪里可以做得更好。</p><h2 id="测试文化的核心-安全与信任" tabindex="-1">测试文化的核心：安全与信任 <a class="header-anchor" href="#测试文化的核心-安全与信任" aria-label="Permalink to &quot;测试文化的核心：安全与信任&quot;">​</a></h2><p>最后说一个技术之外但比任何技术都重要的事：<strong>测试文化。</strong></p><p>一个健康的测试文化有这几个特征：</p><ul><li><strong>Bug 不是耻辱，是信息。</strong> 发现 bug 的人不应该感到&quot;对不起开发&quot;，开发也不应该&quot;被 bug 冒犯&quot;。bug 是流程中的信号，不是对人的否定</li><li><strong>测试人员的声音被听到。</strong> 测试说&quot;这个模块质量风险很高&quot;时，团队会停下来讨论，而不是&quot;你先测着&quot;</li><li><strong>&quot;我不知道&quot;是安全的。</strong> 测试人员和开发一样会碰到自己不懂的东西——问&quot;这个接口的设计意图是什么&quot;比闷头猜一百次更有价值</li><li><strong>安全网够厚。</strong> 有 CI 自动检查、有回归套件、有灰度发布——你要有信心说&quot;我们上线后最坏的情况是什么&quot;</li></ul><p>文化不是一纸规定，是<strong>每个人每天的行为</strong>。你作为一个测试人员，怎么对待发现的 bug、怎么和开发沟通、怎么处理时间压力——你的每一个行为，都在塑造你所在团队的测试文化。</p><h3 id="如果现在的团队离理想很远-从哪里开始" tabindex="-1">如果现在的团队离理想很远，从哪里开始 <a class="header-anchor" href="#如果现在的团队离理想很远-从哪里开始" aria-label="Permalink to &quot;如果现在的团队离理想很远，从哪里开始&quot;">​</a></h3><p>读完这一章，你可能在想：&quot;这些都好，但我的团队现在完全不是这样。&quot;</p><p>《敏捷测试》给了几条实践证明有效的推动策略：</p><ol><li><strong>别试图一次性改变所有东西。</strong> 选一个最小、最能见效的实践先落地——比如&quot;下周开始每个迭代做一次 15 分钟的 Bug Council&quot;。不要同时推自动化、推 CI、推代码审查——你没有那么多能量，团队也没有那么多接受度</li><li><strong>找一个盟友。</strong> 找到团队里一个认同&quot;测试可以更好&quot;的开发或产品，先和他协作。一个人的声音容易被忽略，两个人的声音是对话</li><li><strong>用数据说话，而不是用观点打架。</strong> 不要跟老板说&quot;我们应该做自动化&quot;，说&quot;上次手工回归花了 3 天，自动化后这个模块回归只用了 2 小时&quot;。让结果可见</li><li><strong>庆祝小胜利。</strong> 第一次 Bug Council 让一个模糊的 bug 被快速定位，就在回顾会上提一句。看到效果的人自然会支持下一次</li><li><strong>接受渐进。</strong> 文化改变不是一次会议能完成的。一个月推一个实践，一年就是十二个。每个实践站稳了再推下一个</li></ol><blockquote><p>推动变革的核心不是&quot;证明别人错了&quot;，而是&quot;证明更好的方法是可行的&quot;。</p></blockquote><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>教程到这里全部结束。18 章覆盖了从测试基础理论到现代工程实践的完整体系。</p><p>测试不是软件开发的一个&quot;阶段&quot;，是贯穿始终的质量意识。不管你最终走向管理、架构还是专业测试，能用好这套思维框架，你的决策质量都会上一个台阶。</p><p>剩下的，就是在实际项目中用起来。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>测试人员成长三阶段：会测（执行能力）→ 会想（策略思维）→ 会建（让团队变强）</li><li>团队从个人到集体需要跨过三道坎：知识流动、自动化能力扩散、质量全员负责</li><li>组织层面需要持续投入测试基础设施、用对的方式招聘和培养、用度量驱动改进而不是考核</li><li>健康的测试文化不是规定出来的——Bug 是信息不是耻辱、测试的声音被听到、&quot;不知道&quot;是安全的</li><li>推动变革的五个策略：从小实践开始、找盟友、用数据说话、庆祝小胜利、接受渐进</li></ol>',55)])])}const d=o(i,[["render",r]]);export{p as __pageData,d as default};
